create table if not exists public.nyra_chats (
  id bigint generated by default as identity primary key,
  session_id text not null,
  role text not null,
  content text not null,
  created_at timestamptz not null default now()
);

alter table public.nyra_chats enable row level security;
create policy "read_own" on public.nyra_chats for select using (true);
create policy "insert_any" on public.nyra_chats for insert with check (true);
